-- Homepage FAQ section, placed just before the enquiry form. Run once in the Supabase SQL editor; safe to re-run.
begin;
-- Homepage FAQ, placed just before the enquiry form.
update public.sections set position = position + 1 where page_slug = 'home' and position >= coalesce((select position from public.sections where page_slug = 'home' and key = 'enquiry'), 999) and not exists (select 1 from public.sections where page_slug = 'home' and key = 'faq');
insert into public.sections (page_slug, key, type, label, position, visible, data) values ('home', 'faq', 'faq', 'FAQ', coalesce((select position - 1 from public.sections where page_slug = 'home' and key = 'enquiry'), 999), true, '{"title":"QUESTIONS\nWE GET ASKED","items":[{"q":"What does NexusBee do?","a":"NexusBee is a digital agency in Noida with 7+ years of experience. We design and build websites, web applications, e-commerce stores and mobile apps, run SEO and digital marketing, and build AI agents and business automation for companies across India."},{"q":"Do you work with businesses outside Noida?","a":"Yes. We work with clients all over India, including Delhi NCR, Mumbai, Pune, Bangalore and Hyderabad. Projects run smoothly over video calls, a shared project board and a live staging link."},{"q":"How much does a website or app cost?","a":"It depends on the pages, features and integrations you need. After a short discovery call we send a fixed, written quote, so the price does not change halfway through the project."},{"q":"How long does a project take?","a":"A company website usually takes 4 to 8 weeks, an MVP web or mobile app 8 to 14 weeks, and a first AI automation a few weeks. We agree a timeline with milestones before we start."},{"q":"Will we own the website, code and accounts?","a":"Yes. Your domain, code, hosting, ad accounts and data stay in your name from day one."},{"q":"Do you offer support after launch?","a":"Yes. Monthly maintenance plans cover updates, backups, security, monitoring, content changes and new features, with clear response times."}]}'::jsonb) on conflict (page_slug, key) do nothing;
commit;
